$id=leadReview($db,$o,$p,$key,$form);lcUnit(leadReview($db,$o,$p,$key,$form)===$id,'idempotent');ldDeny(fn()=>leadReview($db,$o,$p,lk(),$form),409);
$replace=array_replace($form,['previous_id'=>$id,'operation'=>'replace','reviewer_id'=>1,'note'=>'Substitute']);$id2=leadReview($db,$o,$p,lk(),$replace);$decision=array_replace($form,['previous_id'=>$id2,'operation'=>'approved','note'=>'Reviewed']);ldDeny(fn()=>leadReview($db,$r,$p,lk(),$decision),403);query($db,'UPDATE github_task_links SET snapshot=? WHERE task_id=?',[$snapshot(str_repeat('b',40)),$t]);ldDeny(fn()=>leadReview($db,$o,$p,lk(),$decision),409);query($db,'UPDATE github_task_links SET snapshot=? WHERE task_id=?',[$snapshot($sha),$t]);leadReview($db,$o,$p,lk(),$decision);lcUnit(leadLatestReview($db,$p,$t)['state']==='approved','review accepted');
